import yaml
import re
import sys
from pathlib import Path

def main():
    config_path = Path(".pre-commit-config.yaml")
    reqs_path = Path("test-requirements.txt")

    if not config_path.exists() or not reqs_path.exists():
        print("Missing config or requirements file")
        sys.exit(1)

    with open(config_path, "r") as f:
        config = yaml.safe_load(f)

    tool_versions = {}
    for repo in config.get("repos", []):
        repo_url = repo.get("repo", "")
        rev = repo.get("rev")
        if not rev:
            continue

        # Clean version string (remove 'v' prefix)
        version = rev[1:] if rev.startswith("v") else rev

        for hook in repo.get("hooks", []):
            hook_id = hook.get("id")
            if hook_id:
                tool_versions[hook_id] = version

    with open(reqs_path, "r") as f:
        lines = f.readlines()

    updated = False
    new_lines = []
    for line in lines:
        # Match package==version and potentially markers
        # Example: black==25.1.0 ; implementation_name == 'cpython'
        match = re.match(r"^([a-zA-Z0-9._-]+)==([a-zA-Z0-9._-]+)(.*)$", line)
        if match:
            package, version, rest = match.groups()
            if package in tool_versions:
                new_version = tool_versions[package]
                if version != new_version:
                    print(f"Updating {package}: {version} -> {new_version}")
                    line = f"{package}=={new_version}{rest}\n"
                    updated = True
        new_lines.append(line)

    if updated:
        with open(reqs_path, "w") as f:
            f.writelines(new_lines)
        print("Updated test-requirements.txt")
    else:
        print("No updates needed")

if __name__ == "__main__":
    main()
